<script setup lang="ts">
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Bell, Check, Plus } from 'lucide-vue-next'
import Modal from '../components/Modal.vue'
import Pager from '../components/Pager.vue'
import DraftNotice from '../components/DraftNotice.vue'
import ConflictNotice from '../components/ConflictNotice.vue'
import HistoryPanel from '../components/HistoryPanel.vue'
import { useConflict,useDraft } from '../drafts'
import { api, dateTimeLabel, dateTimeLocal, isArchived, messageOf, notify, projectName, query, softDelete, ui } from '../api'
import type { Page, Reminder } from '../types'
const props=defineProps<{revision:number}>();const emit=defineEmits<{changed:[];record:[id:string]}>()
const reminders=ref<Reminder[]>([]),total=ref(0),offset=ref(0),status=ref('pending'),project=ref(''),loading=ref(false),error=ref(''),open=ref(false),saving=ref(false),completing=ref(''),editing=ref<Reminder>(),formError=ref('');const limit=30
const form=reactive({title:'',project_id:'',due_local:''}),draft=useDraft(()=>`reminders:${editing.value?.id||'new'}`,form,()=>open.value,()=>editing.value?.version),conflict=useConflict();const readonly=computed(()=>!!editing.value?.done_at||isArchived(form.project_id))
async function load(){loading.value=true;error.value='';try{const page=await api<Page<Reminder>>(`/api/reminders?${query({status:status.value,project_id:project.value,limit,offset:offset.value})}`);reminders.value=page.items;total.value=page.total}catch(e){error.value=messageOf(e)}finally{loading.value=false}}
function assign(reminder?:Reminder){Object.assign(form,{title:reminder?.title||'',project_id:reminder?.project_id||project.value,due_local:dateTimeLocal(reminder?.due_at)})}
async function edit(reminder?:Reminder){if(open.value&&!draft.canLeave())return;editing.value=reminder;assign(reminder);open.value=true;formError.value='';conflict.clear();await draft.reset()}
async function openEntity(id:string){try{await edit(await api<Reminder>(`/api/reminders/${id}`))}catch(e){notify(messageOf(e),true)}}
async function save(){if(saving.value||readonly.value||!form.due_local)return;saving.value=true;formError.value='';const payload={title:form.title,project_id:form.project_id,due_at:new Date(form.due_local).toISOString(),...(editing.value?{version:editing.value.version}:{})};try{const saved=await api<Reminder>(editing.value?`/api/reminders/${editing.value.id}`:'/api/reminders',{method:editing.value?'PATCH':'POST',body:JSON.stringify(payload)});draft.discard();open.value=false;notify(`提醒已保存：${dateTimeLabel(saved.due_at)}`);emit('changed');await load()}catch(e){formError.value=messageOf(e);if(editing.value)await conflict.capture(e,`/api/reminders/${editing.value.id}`,payload)}finally{saving.value=false}}
async function reloadConflict(){const remote=conflict.current.value?.remote as unknown as Reminder;if(!remote)return;draft.persist();editing.value=remote;assign(remote);conflict.clear();await draft.reset()}
async function complete(reminder:Reminder){completing.value=reminder.id;error.value='';try{await api(`/api/reminders/${reminder.id}/done`,{method:'POST',body:JSON.stringify({version:reminder.version})});notify('提醒已标记完成');emit('changed');await load()}catch(e){error.value=messageOf(e)}finally{completing.value=''}}
async function remove(){if(!editing.value||readonly.value)return;try{if(await softDelete('reminders',editing.value,editing.value.title)){draft.discard();open.value=false;emit('changed');await load()}}catch(e){formError.value=messageOf(e)}}
function close(){if(!saving.value&&draft.canLeave())open.value=false}
function page(next:number){offset.value=next;void load()}
onMounted(load);watch(()=>props.revision,load);watch([status,project],()=>{offset.value=0;void load()});defineExpose({openEntity,canLeave:()=>!open.value||draft.canLeave()})
</script>
<template><div class="page-heading"><div><h1>提醒</h1><p class="page-description">一次提醒，到时间后在工作台查看与处理。</p></div><button class="button primary" @click="edit()"><Plus :size="17"/>新建提醒</button></div><div class="filter-bar"><select v-model="status" aria-label="提醒状态"><option value="pending">待完成</option><option value="done">已完成</option><option value="all">全部状态</option></select><select v-model="project" aria-label="提醒所属项目"><option value="">全部项目与未归类</option><option v-for="p in ui.projects" :key="p.id" :value="p.id">{{p.name}}</option></select><span class="input-hint">使用本机时区，无后台系统通知。</span></div><div v-if="error" class="error-banner" role="alert">{{error}}<button class="text-button" @click="load">重试</button></div><div class="surface"><p v-if="loading" class="loading-message">正在读取提醒…</p><div v-else-if="!reminders.length" class="empty-state"><Bell :size="36"/><h2>{{status==='done'?'暂无已完成提醒':'没有待处理提醒'}}</h2><p>为需要跟进的事安排一个明确时间，也可在速记中设置。</p><button class="button subtle small" @click="edit()">新建提醒</button></div><ul v-else class="reminder-list"><li v-for="reminder in reminders" :key="reminder.id"><Bell :size="17" :class="{overdue:!reminder.done_at&&new Date(reminder.due_at).valueOf()<Date.now()}"/><div><button class="table-title" @click="edit(reminder)">{{reminder.title}}</button><p>{{dateTimeLabel(reminder.due_at)}}　{{projectName(reminder.project_id)}}</p><button v-if="reminder.record_id" class="text-button" @click="emit('record',reminder.record_id)">查看关联记录</button></div><span v-if="reminder.done_at" class="badge done">已完成 {{dateTimeLabel(reminder.done_at)}}</span><button v-else class="button subtle small" :disabled="!!completing||isArchived(reminder.project_id)" @click="complete(reminder)"><Check :size="15"/>{{completing===reminder.id?'保存中…':'标记完成'}}</button></li></ul><Pager :offset="offset" :limit="limit" :total="total" @change="page"/></div><Modal :open="open" :title="editing?'提醒详情':'新建一次提醒'" @close="close"><form class="modal-body" @submit.prevent="save"><DraftNotice :value="draft.available.value" :values="draft.values.value" :error="draft.storageError.value" :recovery="draft.recovery.value" @select="draft.select" @restore="draft.restore" @force="draft.restoreForced" @cancel-recovery="draft.clearRecovery" @discard="draft.discardAvailable"/><ConflictNotice :value="conflict.current.value" @keep="draft.persist();conflict.clear()" @reload="reloadConflict"/><fieldset :disabled="readonly||saving"><label>提醒事项<input v-model="form.title" required maxlength="200" autofocus placeholder="需要跟进什么？"/></label><label>提醒时间（本地）<input v-model="form.due_local" type="datetime-local" required/></label><label>关联项目<select v-model="form.project_id"><option value="">未归类</option><option v-for="p in ui.projects.filter(p=>p.status!=='archived'||p.id===form.project_id)" :key="p.id" :value="p.id">{{p.name}}</option></select></label></fieldset><p class="input-hint">到时在今日工作台显示；不会发送系统、邮件或手机通知。</p><HistoryPanel v-if="editing" kind="reminders" :id="editing.id" :revision="editing.version"/><p v-if="formError" class="form-error" role="alert">{{formError}}</p><div class="modal-footer"><span v-if="readonly" class="muted">已完成或归档的提醒只读</span><button v-if="editing&&!readonly" type="button" class="button subtle small" @click="remove">移入回收站</button><button v-if="!readonly" class="button primary" :disabled="saving">{{saving?'正在保存…':'保存提醒'}}</button></div></form></Modal></template>
